import time
import logging
from taf.transport.ssh import ssh


class SshExecutor(object):

    def __init__(self, config):
        self._config = config
        self.ssh = ssh()
        self.alias = 'ip:' + self._config['addr'] + '_' + str(int(time.time() * 1000))
        self.connect_to()

    def connect_to(self):
        """
        connect to ip with name and password, port
        """

        self.ssh.connect_to(
            hostname=self._config['addr'],
            username=self._config['username'],
            password=self._config['password'],
            port=None,
            alias=self.alias)

    def disconnect(self):
        """
        disconnect with ssh
        """
        try:
            self.ssh.disconnect(self.alias)
        except BaseException:
            pass

    def execute(self, command, timeout=None):
        """
        execute command through ssh
        :return str : output after command execute
        """
        if not command:
            raise Exception("invalid input")

        stripped_command = command.strip() + '\n'
        time.sleep(1)

        logging.info("{} finally execute command {}".format(self.alias, stripped_command))
        return self.ssh.execute(command=stripped_command, timeout=timeout, connection=self.alias)

    def send_command(self, command, get_pty=True, timeout="300s"):
        """
        execute command through ssh
        """
        if not command:
            raise Exception("invalid input")

        stripped_command = command.strip() + '\n'
        time.sleep(1)

        logging.info("{} finally execute command {}".format(self.alias, stripped_command))
        self.ssh.send_command(command=stripped_command, get_pty=get_pty, connection=self.alias, timeout=timeout)

    def read_output(self):
        return self.ssh.read_output(connection=self.alias)
